// Generate the canonical W-Sim WASM bytes from this versioned source crate.
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const crate = fileURLToPath(new URL('../', import.meta.url));
const args = process.argv.slice(2);
const targetIndex = args.indexOf('--target');
if (targetIndex < 0 || !args[targetIndex + 1]) {
  throw new Error('usage: node wasm/build-kernels.mjs --target <wasm-kernel.ts> [--check]');
}
const target = resolve(args[targetIndex + 1]);
const check = args.includes('--check');

function rustSources(dir) {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => entry.isDirectory()
    ? rustSources(join(dir, entry.name))
    : entry.name.endsWith('.rs') ? [join(dir, entry.name)] : []);
}

const input = [...rustSources(join(crate, 'src')), join(crate, 'wasm/abi.rs')].sort();
const hash = createHash('sha256');
for (const path of input) {
  hash.update(relative(crate, path)).update('\0').update(readFileSync(path)).update('\0');
}
const digest = hash.digest('hex');
if (check) {
  if (!readFileSync(target, 'utf8').includes(`WASM_KERNEL_SOURCE_SHA256 = '${digest}'`)) {
    throw new Error(`W-Sim WASM sources changed; regenerate ${target} with this crate's build tool`);
  }
  console.log(`W-Sim WASM sources match ${digest}`);
} else {
  const scratch = mkdtempSync(join(tmpdir(), 'w-sim-kernels-build-'));
  try {
    const library = join(scratch, 'libw_sim_kernels.rlib');
    const wasm = join(scratch, 'kernels.wasm');
    execFileSync('rustc', [join(crate, 'src/lib.rs'), '--edition', '2021', '--crate-name', 'w_sim_kernels', '--crate-type', 'rlib',
      '--target', 'wasm32-unknown-unknown', '-O', '-C', 'panic=abort', '-C', 'target-feature=+simd128', '-o', library], { stdio: 'inherit', timeout: 60000 });
    execFileSync('rustc', [join(crate, 'wasm/abi.rs'), '--extern', `w_sim_kernels=${library}`, '--edition', '2021',
      '--target', 'wasm32-unknown-unknown', '--crate-type', 'cdylib', '-O', '-C', 'panic=abort', '-C', 'target-feature=+simd128',
      '-C', 'link-arg=--strip-all', '-C', 'link-arg=-zstack-size=16384', '-o', wasm], { stdio: 'inherit', timeout: 60000 });
    const bytes = readFileSync(wasm);
    if (!WebAssembly.validate(bytes)) throw new Error('Invalid generated W-Sim WASM');
    writeFileSync(target, '// Generated by w-sim-kernels/wasm/build-kernels.mjs; edit the Rust source crate.\n'
      + `export const WASM_KERNEL_SOURCE_SHA256 = '${digest}'\n`
      + `export const WASM_KERNEL_BASE64 = '${bytes.toString('base64')}'\n`);
    console.log(`W-Sim WASM kernel: ${bytes.length} bytes, source ${digest}`);
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }
}
